import math
import unittest
from solution import lower_bound


class Reader:
    def __init__(self, data=None, n=0, fn=None, limit=500):
        self.data = data
        self.n = len(data) if data is not None else n
        self.fn = fn
        self.calls = 0
        self.limit = limit

    def get(self, i):
        if i < 0:
            raise ValueError("negative index: " + repr(i))
        self.calls += 1
        if self.calls > self.limit:
            raise RuntimeError("too many reader.get calls (possible infinite loop)")
        if i >= self.n:
            return None
        if self.data is not None:
            return self.data[i]
        return self.fn(i)


def budget(n):
    return 3 * math.log2(n + 2) + 20


class T(unittest.TestCase):
    def _run(self, reader, target, expected):
        got = lower_bound(reader, target)
        self.assertEqual(got, expected)
        self.assertLessEqual(reader.calls, budget(reader.n))

    def test_basic(self):
        self._run(Reader([1, 3, 5, 7]), 5, 2)

    def test_between(self):
        self._run(Reader([1, 3, 5, 7]), 4, 2)

    def test_all_smaller(self):
        self._run(Reader([1, 3, 5, 7]), 8, 4)

    def test_answer_is_zero(self):
        self._run(Reader([5, 6, 7]), 0, 0)

    def test_empty_stream(self):
        self._run(Reader([]), 1, 0)

    def test_dups_first(self):
        self._run(Reader([2, 2, 2, 2]), 2, 0)

    def test_dups_all_smaller(self):
        self._run(Reader([2, 2, 2, 2]), 3, 4)

    def test_single_small_target(self):
        self._run(Reader([7]), 1, 0)

    def test_single_large_target(self):
        self._run(Reader([7]), 8, 1)

    def test_overshoot_no_type_error(self):
        self._run(Reader([1, 2, 3]), 10**6, 3)

    def test_huge_middle(self):
        self._run(Reader(n=10**9, fn=lambda i: 2 * i), 10**6, 500000)

    def test_huge_last(self):
        self._run(Reader(n=10**9, fn=lambda i: 2 * i), 1999999998, 999999999)

    def test_huge_past_end(self):
        self._run(Reader(n=10**9, fn=lambda i: 2 * i), 1999999999, 10**9)

    def test_huge_before_start(self):
        self._run(Reader(n=10**9, fn=lambda i: 2 * i), -5, 0)


if __name__ == "__main__":
    unittest.main()

