import unittest
from solution import paginate

LOG = ["m%d" % i for i in range(1, 11)]


def gen(seq):
    for x in seq:
        yield x


class OneShot:
    def __init__(self, seq):
        self._it = iter(list(seq))
        self._used = False

    def __iter__(self):
        if self._used:
            raise RuntimeError("iterated twice")
        self._used = True
        return self._it


class BareIterator:
    def __init__(self, seq):
        self._it = iter(list(seq))

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._it)


class Tracked:
    live = 0
    peak = 0

    def __init__(self, i):
        self.i = i
        Tracked.live += 1
        if Tracked.live > Tracked.peak:
            Tracked.peak = Tracked.live

    def __del__(self):
        Tracked.live -= 1


class T(unittest.TestCase):
    def test_generator_pages(self):
        self.assertEqual(paginate(gen(LOG), 1, 3), ["m8", "m9", "m10"])
        self.assertEqual(paginate(gen(LOG), 2, 3), ["m5", "m6", "m7"])
        self.assertEqual(paginate(gen(LOG), 3, 3), ["m2", "m3", "m4"])

